/**
 * Конфигурация триггера агента.
 * 
 * Payload автоматически записывается в state.triggers.{trigger_id}.
 * output_mapping определяет какие данные куда положить в state.
 * 
 * Пример:
 * {
 *     "trigger_id": "tg_support",
 *     "name": "Telegram Support Bot",
 *     "type": "telegram",
 *     "enabled": true,
 *     "config": {
 *         "bot_token": "@var:telegram_bot_token"
 *     },
 *     "output_mapping": {
 *         "content": "message.text",
 *         "context.chat_id": "message.chat.id"
 *     }
 * }
 * 
 * Формат output_mapping: слева только content и/или context.*; variables.* запрещены.
 */
export interface TriggerConfig {
    /**
     * Уникальный ID триггера (без «.» в id)
     */
    "trigger_id": string;
    /**
     * Название триггера
     */
    "name": string;
    /**
     * Тип триггера
     */
    "type": TriggerType;
    /**
     * Активен ли триггер
     */
    "enabled"?: boolean | undefined;
    /**
     * Конфигурация триггера (bot_token, cron, etc.)
     */
    "config"?: Record<string, JsonValue> | undefined;
    /**
     * Маппинг payload path -> state path
     */
    "output_mapping"?: Record<string, string> | undefined;
    /**
     * DEPRECATED: используйте output_mapping
     */
    "input_mapping"?: Record<string, string> | undefined;
    /**
     * Действия отправки ответа в канал после выполнения агента
     */
    "output_actions"?: OutputAction[] | undefined;
    /**
     * Выполнять output_actions после завершения flow (без interrupt)
     */
    "post_flow_output_enabled"?: boolean | undefined;
    /**
     * ID ветки из FlowConfig.branches: какой сценарий запускать при срабатывании триггера
     */
    "branch_id"?: string | undefined;
    /**
     * URL webhook (генерируется при регистрации)
     */
    "webhook_url"?: string | null | undefined;
    /**
     * ID в TaskIQ scheduler (для cron)
     */
    "schedule_id"?: string | null | undefined;
    /**
     * Текущий статус триггера
     */
    "status"?: TriggerStatus | undefined;
    /**
     * Последняя ошибка (если status=error)
     */
    "last_error"?: string | null | undefined;
    [key: string]: unknown;
}

